void read_input(int *n, int *k, int *x, int values[]) {
    scanf("%d %d %d", n, k, x);
    for (int i = 0; i < *n; i++) scanf("%d", &values[i]);
}

void insert_and_print(int n, int k, int x, int values[]) {
    for (int i = 0; i < n + 1; i++) {
        if (i < k) printf("%d ", values[i]);
        else if (i == k) printf("%d ", x);
        else printf("%d ", values[i - 1]);
    }
    printf("\n");
}

int main() {
    int n, k, x, values[105];
    read_input(&n, &k, &x, values);
    insert_and_print(n, k, x, values);
    return 0;
}
